//! @file
//! @brief RAII timer class for automatic histogram timing
#pragma once

#include <omni/observability/IMetrics.h>
#include <carb/ObjectUtils.h>
#include <chrono>
#include <type_traits>
#include <vector>

namespace omni
{
namespace observability
{

/** RAII timer class that automatically records elapsed time to a histogram on scope exit.
 *
 *  This class provides convenient automatic timing for histogram metrics. It starts timing
 *  on construction and records the elapsed duration to the histogram when destroyed,
 *  unless cancelled. The duration is recorded in seconds for floating-point types or
 *  milliseconds for integer types, depending on the ValueType template parameter.
 *
 *  Attributes (metadata) can be associated with timing measurements by passing them to the
 *  stop() method. This allows you to categorize measurements by various dimensions such as
 *  status codes, operation types, or other contextual information.
 *
 *  @warning **Attribute Cardinality**: Each unique combination of attribute key-value pairs
 *           creates a separate time series in your metrics backend. Adding more attributes
 *           increases the total number of time series stored, as the number of time series
 *           grows with the product of unique values across all attributes. For example, if
 *           you have 3 status values, 10 endpoint values, and 5 region values, you could
 *           create up to 150 time series (3 × 10 × 5). Use attributes judiciously to avoid
 *           excessive storage requirements and query costs.
 *
 *  @thread_safety Concurrent access to the same HistogramTimer instance from multiple threads
 *                 requires external synchronization. Each thread can safely create and use its
 *                 own HistogramTimer instance. The underlying histogram recording is thread-safe.
 *
 *  @warning **Fiber-based Tasks**: When using fiber-based task systems (such as carb::tasking),
 *           be aware that the underlying metrics implementation uses thread-local storage for
 *           meter caching. If a fiber is suspended and resumed on a different thread, the
 *           HistogramTimer may access a different thread-local cache, potentially leading to
 *           inconsistent results or unexpected behavior. For fiber-based code, consider using
 *           timers only within non-yielding sections or ensuring the entire timing operation
 *           completes on the same thread.
 *
 *  @tparam ValueType The numeric type for the histogram values (default: double).
 *                    Only double and std::uint64_t are supported by the metrics system.
 *                    - double: Records time in seconds with sub-second precision.
 *                    - std::uint64_t: Records time in milliseconds.
 *
 *  @code
 *  // Example 1: Basic usage with default attributes (records in seconds)
 *  {
 *      HistogramTimer<double> timer(myHistogram);
 *      // ... perform timed operation ...
 *  } // Automatically records duration when timer goes out of scope
 *
 *  // Example 2: Use uint64_t for millisecond precision
 *  {
 *      HistogramTimer<uint64_t> timer(myHistogramUint);
 *      // ... perform timed operation ...
 *  } // Automatically records duration in milliseconds
 *
 *  // Example 3: Add a single attribute at stop time
 *  {
 *      HistogramTimer<double> timer(myHistogram);
 *      // ... perform operation ...
 *      if (success)
 *          timer.stop("status", "success");
 *      else
 *          timer.stop("status", "error");
 *  }
 *
 *  // Example 4: Add multiple attributes at stop time
 *  {
 *      HistogramTimer<double> timer(myHistogram);
 *      // ... perform operation ...
 *      timer.stop({
 *          {"status", "success"},
 *          {"endpoint", "/api/users"},
 *          {"method", "GET"}
 *      });
 *  }
 *
 *  // Example 5: Cancel timing
 *  {
 *      HistogramTimer<double> timer(myHistogram);
 *      // ... perform operation ...
 *      if (shouldNotRecord)
 *          timer.cancel();
 *  }
 *
 *  // Example 6: Use with type-based histogram
 *  using MyLatencyHistogram = omni::observability::Histogram<MyMeter, LatencyInstrument, double>;
 *  {
 *      HistogramTimer<double> timer(MyLatencyHistogram::getInstrument());
 *      // ... perform timed operation ...
 *  }
 *  @endcode
 */
template <class ValueType = double>
class HistogramTimer
{
    static_assert(std::is_integral_v<ValueType> || std::is_floating_point_v<ValueType>,
                  "ValueType must be an integral or floating-point type");

public:
    /** Construct a timer for the given histogram (ObjectPtr version).
     *
     *  @param[in] histogram The histogram to record the elapsed time to.
     *
     *  @remarks The timer starts measuring elapsed time immediately upon construction.
     *           If the histogram pointer is null, the timer will operate but not record any metrics.
     *           This constructor takes ownership of the histogram reference, ensuring it remains
     *           valid for the lifetime of the timer.
     *
     *  @note See the ValueType template parameter documentation for time unit details (seconds vs milliseconds).
     */
    explicit HistogramTimer(carb::ObjectPtr<IHistogram<ValueType>> histogram) noexcept
        : m_histogram(std::move(histogram)), m_startTime(std::chrono::steady_clock::now()), m_cancelled(false)
    {
    }

    /** Destructor - records the elapsed time to the histogram unless cancelled.
     *
     *  @remarks If stop() was already called, this will not record again.
     *           If cancel() was called, this will not record.
     *
     *  @note See the ValueType template parameter documentation for time unit details (seconds vs milliseconds).
     *
     *  @thread_safety Requires external synchronization for concurrent access to the same instance.
     */
    ~HistogramTimer() noexcept
    {
        if (!m_cancelled && m_histogram)
        {
            recordElapsed();
        }
    }

    /** Stop the timer and record the elapsed time with no additional attributes.
     *
     *  @remarks This stops the timer and immediately records the elapsed time.
     *           The destructor will not record again if stop() was already called.
     *           Calling stop() multiple times is safe but only the first call records the metric.
     *
     *  @note After calling stop(), the timer object is no longer usable and should not be
     *        restarted or reused. Create a new HistogramTimer instance for subsequent measurements.
     *
     *  @note See the ValueType template parameter documentation for time unit details (seconds vs milliseconds).
     *
     *  @thread_safety Requires external synchronization for concurrent access to the same instance.
     */
    void stop() noexcept
    {
        if (!m_cancelled && m_histogram)
        {
            recordElapsed();
            m_cancelled = true; // Prevent recording again in destructor
        }
    }

    /** Stop the timer and record the elapsed time with a single attribute.
     *
     *  @param[in] key The attribute key.
     *  @param[in] value The attribute value.
     *
     *  @remarks This stops the timer and immediately records the elapsed time with the given attribute.
     *           The destructor will not record again if stop() was already called.
     *
     *  @note After calling stop(), the timer object is no longer usable and should not be
     *        restarted or reused. Create a new HistogramTimer instance for subsequent measurements.
     *
     *  @note See the ValueType template parameter documentation for details on how time values are stored.
     *
     *  @warning Be mindful of attribute cardinality. Adding attributes increases the total
     *           number of time series stored, as each unique combination of attributes
     *           creates a separate time series in your metrics backend.
     *
     *  @thread_safety Requires external synchronization for concurrent access to the same instance.
     */
    template <class T>
    void stop(carb::cpp::string_view key, T value) noexcept
    {
        if (!m_cancelled && m_histogram)
        {
            ValueType elapsed = calculateElapsed();
            m_histogram->record(elapsed, { Attribute(key, value) });
            m_cancelled = true; // Prevent recording again in destructor
        }
    }

    /** Stop the timer and record the elapsed time with multiple attributes.
     *
     *  @param[in] attributes Initializer list of attributes to associate with the timing measurement.
     *
     *  @remarks This stops the timer and immediately records the elapsed time with the given attributes.
     *           The destructor will not record again if stop() was already called.
     *
     *  @note After calling stop(), the timer object is no longer usable and should not be
     *        restarted or reused. Create a new HistogramTimer instance for subsequent measurements.
     *
     *  @note See the ValueType template parameter documentation for details on how time values are stored.
     *
     *  @warning Be mindful of attribute cardinality. Adding attributes increases the total
     *           number of time series stored, as each unique combination of attributes
     *           creates a separate time series in your metrics backend.
     *
     *  @thread_safety Requires external synchronization for concurrent access to the same instance.
     */
    void stop(std::initializer_list<Attribute> attributes) noexcept
    {
        if (!m_cancelled && m_histogram)
        {
            ValueType elapsed = calculateElapsed();
            m_histogram->record(elapsed, attributes);
            m_cancelled = true; // Prevent recording again in destructor
        }
    }

    /** Stop the timer and record the elapsed time with variadic attributes.
     *
     *  @param[in] a Variadic list of attributes to associate with the timing measurement.
     *
     *  @remarks This stops the timer and immediately records the elapsed time with the given attributes.
     *           The destructor will not record again if stop() was already called.
     *
     *  @note After calling stop(), the timer object is no longer usable and should not be
     *        restarted or reused. Create a new HistogramTimer instance for subsequent measurements.
     *
     *  @note See the ValueType template parameter documentation for details on how time values are stored.
     *
     *  @warning Be mindful of attribute cardinality. Adding attributes increases the total
     *           number of time series stored, as each unique combination of attributes
     *           creates a separate time series in your metrics backend.
     *
     *  @thread_safety Requires external synchronization for concurrent access to the same instance.
     */
    template <class... A>
    void stop(A&&... a) noexcept
    {
        if (!m_cancelled && m_histogram)
        {
            ValueType elapsed = calculateElapsed();
            m_histogram->record(elapsed, std::forward<A>(a)...);
            m_cancelled = true; // Prevent recording again in destructor
        }
    }

    /** Cancel the timer, preventing any recording.
     *
     *  @remarks After calling cancel(), the timer will not record any metrics,
     *           even when destroyed. This is useful when you want to conditionally
     *           skip timing measurements.
     *
     *  @thread_safety Requires external synchronization for concurrent access to the same instance.
     */
    void cancel() noexcept
    {
        m_cancelled = true;
    }

    /** Get the elapsed time since the timer was started.
     *
     *  @returns The elapsed time as the ValueType (seconds for floating-point, milliseconds for integers).
     *
     *  @remarks This does not stop the timer or record any metrics.
     *
     *  @note See the ValueType template parameter documentation for time unit details (seconds vs milliseconds).
     *
     *  @thread_safety Safe to call concurrently from multiple threads on the same instance,
     *                 provided no other thread is modifying the instance (e.g., calling stop()
     *                 or cancel()).
     */
    ValueType elapsed() const noexcept
    {
        return calculateElapsed();
    }

    // Disable copying and moving
    HistogramTimer(const HistogramTimer&) = delete;
    HistogramTimer& operator=(const HistogramTimer&) = delete;
    HistogramTimer(HistogramTimer&&) = delete;
    HistogramTimer& operator=(HistogramTimer&&) = delete;

private:
    /** Calculate elapsed time in seconds (for floating-point types) or milliseconds (for integer types). */
    ValueType calculateElapsed() const noexcept
    {
        auto now = std::chrono::steady_clock::now();
        if constexpr (std::is_integral_v<ValueType>)
        {
            // For integer types, return milliseconds
            auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(now - m_startTime);
            return static_cast<ValueType>(duration.count());
        }
        else
        {
            // For floating-point types, return seconds
            auto duration = std::chrono::duration_cast<std::chrono::duration<double>>(now - m_startTime);
            return static_cast<ValueType>(duration.count());
        }
    }

    /** Record elapsed time with stored attributes. */
    void recordElapsed() noexcept
    {
        if (m_histogram)
        {
            ValueType elapsed = calculateElapsed();
            m_histogram->record(elapsed);
        }
    }

    carb::ObjectPtr<IHistogram<ValueType>> m_histogram;
    std::chrono::steady_clock::time_point m_startTime;
    bool m_cancelled;
};

} // namespace observability
} // namespace omni
